def scope_members(scope):
    kind = scope['kind']
    if kind == 'explicit':
        paths = [plain(x) for x in scope['paths']]
        need(all(x.is_file() for x in paths), 'Explicit file member missing')
    elif kind == 'tree':
        root = plain(scope['root'])
        allnames = walk(root)
        paths = [root / n for n in allnames if not n.endswith('/') and (scope['recursive'] or '/' not in n)]
        paths = [p for p in paths if (not scope['extensions'] or p.suffix.lower() in scope['extensions']) and (not scope['excluded_part'] or scope['excluded_part'].lower() not in str(p).lower())]
    elif kind == 'pefile_module':
        root = plain(scope['root'])
        paths = [root / 'pefile.py']
        cache = root / '__pycache__'
        if cache.exists():
            plain(cache)
            paths += [plain(p) for p in cache.glob('pefile.*.pyc') if p.is_file()]
        paths = [p for p in paths if p.is_file()]
    elif kind == 'site_startup':
        paths = []
        for value in scope['roots']:
            root = plain(value)
            for p in root.iterdir():
                plain(p)
                if p.is_file() and (p.suffix.lower() == '.pth' or p.name.lower() in ('sitecustomize.py', 'usercustomize.py')):
                    paths.append(p)
    else:
        raise RuntimeError('Unsupported scope kind')
    result = sorted({str(canonical(p)) for p in paths}, key=str.casefold)
    need(len(result) == len({x.casefold() for x in result}), 'Unique scope paths')
    return result

def collect_memberships(scopes, originals):
    need(len({s['category'] for s in scopes}) == len(scopes), 'Unique scope categories')
    rows = []
    for scope in scopes:
        for path in scope_members(scope):
            need(key(path) in originals, 'Every complete scope member has a reviewed file pin: ' + path)
            checked_pin(originals[key(path)])
            rows.append({'category': scope['category'], 'original': str(canonical(path))})
    return rows

def recheck_base(base):
    originals = {}
    for pair in base['files']:
        checked_pin(pair['original'])
        checked_pin(pair['frozen'])
        need(pair['original']['bytes'] == pair['frozen']['bytes'] and pair['original']['sha256'] == pair['frozen']['sha256'], 'Full fresh copy equality')
        need(key(pair['original']['path']) not in originals, 'Unique originals')
        originals[key(pair['original']['path'])] = pair['original']
    need(collect_memberships(base['scopes'], originals) == base['memberships'], 'Full selected membership identity')

def prepare_contract(plan, base):
    draft = Path(base['draft'])
    copies = []
    for role, name in STAGED.items():
        copies.append({'relative_path': name, 'source': pin(draft / DRAFT[role])})
    copies.extend({'relative_path': target, 'source': pin(draft / source)} for source, target in [('type1011_probe.cpp.txt', 'type1011_probe.cpp'), ('artifact_manifest.json', 'draft_manifest.json'), ('receipt.json', 'draft_receipt.json'), ('frozen_cases/expected_case_matrix.json', 'cases.json')])
    books = read(pin(draft / 'input_bookends_before.json'))
    for row in books:
        if row['kind'] == 'Source':
            name = PureWindowsPath(row['copy']).relative_to('frozen_Source').as_posix()
            source = pin(ROOT / name)
            need((source['bytes'], source['sha256']) == (row['bytes'], row['sha256']), 'Current Source12 exact draft pins')
            copies.append({'relative_path': name, 'source': source})
    need(sum(r['kind'] == 'Source' for r in books) == 12, 'Full Source12')
    for name, target in [('tools/ghidra_export.py', 'query_helper.py'), ('config/target.json', 'target.json')]:
        if target == 'query_helper.py':
            source = selected_prepare_query(base)
        else:
            source = pin(ROOT / name)
            frozen = pin(draft / 'frozen_context' / name)
            need(source['bytes'] == 455 and source['sha256'] == '366e5a64ac945473bb8d91607a78e56fee52e2579d38e66df3c240000b108ffb' and read(source) == read(frozen), 'Original recipe requires exact current455 config and semantic historical config equality')
        copies.append({'relative_path': target, 'source': source})
    dependencies = {}
    for name in ('capstone', 'pefile', 'ordlookup'):
        item = plan['package_modules'][name]
        source = canonical(item['path'])
        paths = [source.parent / n for n in walk(source.parent) if not n.endswith('/')] if item['package'] else [source]
        for p in paths:
            dependencies[key(p)] = pin(p)
    python_home = canonical(plan['python_executable']['path']).parent
    for folder in (python_home / 'Lib', python_home / 'DLLs'):
        plain(folder)
        for directory, dirs, files in os.walk(folder, followlinks=False):
            plain(directory)
            for d in dirs:
                plain(Path(directory) / d)
            dirs[:] = [d for d in dirs if d.lower() not in ('site-packages', 'test', 'tests', 'idle_test')]
            for name in files:
                p = plain(Path(directory) / name)
                dependencies[key(p)] = pin(p)
    for p in python_home.glob('python*.zip'):
        dependencies[key(p)] = pin(p)
    originals = {key(r['original']['path']): r['original'] for r in base['files']}
    for p in dependencies.values():
        need(originals.get(key(p['path'])) == p, 'Full prepare dependency belongs to independently selected closure')
    return copies, sorted(dependencies.values(), key=lambda p: p['path'])

def unique_pins(rows):
    result = {}
    for row in rows:
        checked_pin(row)
        k = key(row['path'])
        need(k not in result or result[k] == row, 'Conflicting pin for one canonical input')
        result[k] = row
    return result

def read_manual_data(row):
    """Read only a fully pinned closed JSON file; reject duplicate keys."""
    checked_pin(row)
    data = Path(row['path']).read_bytes()
    need(len(data) == row['bytes'] and hashlib.sha256(data).hexdigest() == row['sha256'], 'Closed manual DATA read changed')
    def pairs(items):
        result = {}
        for name, value in items:
            need(name not in result, 'Duplicate JSON key in closed manual DATA')
            result[name] = value
        return result
    def constant(value):
        need(False, 'Non-finite JSON value in closed manual DATA: ' + value)
    def finite_float(token):
        number = float(token)
        need(-float('inf') < number < float('inf'), 'Non-finite JSON floating-point value in closed manual DATA: ' + token)
        return number
    value = json.loads(data, object_pairs_hook=pairs, parse_constant=constant, parse_float=finite_float)
    checked_pin(row)
    return value

def change_contract(old_pin, target, schema):
    obj = read(old_pin)
    need(obj['schema'] == schema and obj['Root_acceptance'] is False and obj['Source_credit'] == 0, 'Only an unadopted selected contract can be adopted')
    obj['Root_acceptance'] = True
    if 'status' in obj:
        obj['status'] = 'Root-authorized DATA adoption; no dispatch or runtime fact'
    return save(target, obj)
